// src/pages/about.tsx
import * as React from "react";
import type { HeadFC, PageProps } from "gatsby";
import { graphql } from "gatsby";
import { useTranslation } from "gatsby-plugin-react-i18next";
import Link from "../components/AppLink";

import Layout from "../components/Layout";
import data from "../data/data.json";
import type { Company } from "../interfaces";
import SEO from "../components/seo";
import images from "../images";
import { useEffect } from "react";

const info: Company = data[0];

type Bullet = { item: string };
type Stat = { value: string; label: string };
type ValueCard = { title: string; text: string };
type Faq = { q: string; a: string };

const AboutPage: React.FC<PageProps> = () => {
  const { t } = useTranslation();

  useEffect(() => {
    document.body.style.backgroundImage = `url(${images.bg.src})`;
    document.body.style.backgroundSize = "cover";
    document.body.style.backgroundPosition = "center";
    document.body.style.backgroundRepeat = "no-repeat";

    return () => {
      document.body.style.backgroundImage = "";
      document.body.style.backgroundSize = "";
      document.body.style.backgroundPosition = "";
      document.body.style.backgroundRepeat = "";
    };
  }, []);

  const chips = t("about.hero.chips", { returnObjects: true }) as Array<{
    chip: string;
  }>;
  const stats = t("about.stats.items", { returnObjects: true }) as Stat[];
  const services = t("about.services.items", {
    returnObjects: true,
  }) as Bullet[];
  const differentiators = t("about.differentiators.items", {
    returnObjects: true,
  }) as Bullet[];
  const values = t("about.values.items", {
    returnObjects: true,
  }) as ValueCard[];
  const faq = t("about.faq.items", { returnObjects: true }) as Faq[];

  const mailSubject = encodeURIComponent(
    t("about.cta.emailSubject") || "Inquiry about Services"
  );
  const mailto = `mailto:${info.email}?subject=${mailSubject}`;

  return (
    <Layout data={info}>
      <SEO
        data={info}
        titleKey="about.metaTitle"
        descriptionKey="about.metaDescription"
        pathname="/about/"
        schemaType="ProfessionalService"
      />

      {/* HERO */}
      <section className="pt-10 pb-6 sm:pt-14 sm:pb-10">
        <div className={styles.container}>
          <div className="text-center">
            <h1 className="text-3xl sm:text-5xl poppins-bold text-light mx-auto max-w-5xl">
              {t("about.hero.title")}
            </h1>

            <p className="mt-4 text-lg sm:text-2xl poppins-regular text-light/90 mx-auto max-w-4xl">
              {t("about.hero.subtitle")}
            </p>

            <div className="mx-auto mt-8 flex flex-col sm:flex-row items-center justify-center gap-3">
              <Link
                to="/contact/"
                className="rounded-full bg-secondary px-5 py-2.5 text-light text-center"
              >
                {t("about.cta.primary")}
              </Link>

              <a
                href={mailto}
                className="rounded-full bg-purplesemilight px-5 py-2.5 text-light text-center"
              >
                {t("about.cta.secondary")}
              </a>
            </div>

            {Array.isArray(chips) && chips.length > 0 ? (
              <div className="mx-auto mt-6 flex flex-wrap items-center justify-center gap-2 max-w-4xl">
                {chips.map((c, idx) => (
                  <span
                    key={`${c.chip}-${idx}`}
                    className="inline-flex items-center rounded-full border border-white/20 bg-white/10 px-3 py-1 text-sm text-light/90"
                  >
                    {c.chip}
                  </span>
                ))}
              </div>
            ) : null}
          </div>
        </div>
      </section>

      {/* STORY */}
      <section className="py-10 sm:py-14">
        <div className={styles.container}>
          <div className="mx-auto max-w-4xl">
            <h2 className="text-2xl sm:text-4xl text-center poppins-regular text-verde">
              {t("about.story.title")}
            </h2>

            <div className="mt-8 space-y-4">
              <p className="text-sm sm:text-base text-light/80 leading-relaxed">
                {t("about.story.p1")}
              </p>
              <p className="text-sm sm:text-base text-light/80 leading-relaxed">
                {t("about.story.p2")}
              </p>
              <p className="text-sm sm:text-base text-light/80 leading-relaxed">
                {t("about.story.p3")}
              </p>
            </div>
          </div>
        </div>
      </section>

      {/* STATS */}
      <section className="py-10 sm:py-14">
        <div className={styles.container}>
          <h2 className="text-2xl sm:text-4xl text-center poppins-regular text-verde">
            {t("about.stats.title")}
          </h2>

          <div className="mt-8 grid grid-cols-1 sm:grid-cols-3 gap-4">
            {Array.isArray(stats)
              ? stats.map((s, idx) => (
                  <div key={`${s.value}-${idx}`} className={styles.card}>
                    <div className="text-2xl sm:text-3xl font-semibold text-light/90">
                      {s.value}
                    </div>
                    <div className="mt-1 text-sm sm:text-base text-light/70">
                      {s.label}
                    </div>
                  </div>
                ))
              : null}
          </div>
        </div>
      </section>

      {/* WHAT WE DO */}
      <section className="py-10 sm:py-14">
        <div className={styles.container}>
          <div className="mx-auto max-w-4xl">
            <h2 className="text-2xl sm:text-4xl text-center poppins-regular text-verde">
              {t("about.services.title")}
            </h2>

            <p className="mt-4 text-sm sm:text-base text-center text-light/70">
              {t("about.services.subtitle")}
            </p>

            <div className="mt-8">
              <div className={styles.card}>
                <ul className="list-disc pl-5 space-y-2 text-sm sm:text-base text-light/80">
                  {Array.isArray(services)
                    ? services.map((x, idx) => (
                        <li key={`${x.item}-${idx}`}>{x.item}</li>
                      ))
                    : null}
                </ul>

                <div className="mt-6 flex flex-col sm:flex-row items-center justify-center gap-3">
                  <Link
                    to="/services/"
                    className="rounded-full bg-secondary px-5 py-2.5 text-light text-center"
                  >
                    {t("about.services.cta")}
                  </Link>
                  <Link
                    to="/#portfolio"
                    className="text-sm underline text-light/70"
                  >
                    {t("about.services.secondaryCta")}
                  </Link>
                </div>
              </div>
            </div>
          </div>
        </div>
      </section>

      {/* DIFFERENTIATORS */}
      <section className="py-10 sm:py-14">
        <div className={styles.container}>
          <div className="mx-auto max-w-4xl">
            <h2 className="text-2xl sm:text-4xl text-center poppins-regular text-verde">
              {t("about.differentiators.title")}
            </h2>

            <div className="mt-8">
              <div className={styles.card}>
                <ul className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                  {Array.isArray(differentiators)
                    ? differentiators.map((x, idx) => (
                        <li
                          key={`${x.item}-${idx}`}
                          className="rounded-xl border border-black/10 bg-white/50 p-4"
                        >
                          <p className="text-sm sm:text-base text-light/80">
                            {x.item}
                          </p>
                        </li>
                      ))
                    : null}
                </ul>
              </div>
            </div>
          </div>
        </div>
      </section>

      {/* VALUES */}
      <section className="py-10 sm:py-14">
        <div className={styles.container}>
          <div className="mx-auto max-w-5xl">
            <h2 className="text-2xl sm:text-4xl text-center poppins-regular text-verde">
              {t("about.values.title")}
            </h2>

            <div className="mt-8 grid grid-cols-1 md:grid-cols-3 gap-4">
              {Array.isArray(values)
                ? values.map((v, idx) => (
                    <div key={`${v.title}-${idx}`} className={styles.card}>
                      <h3 className="text-base sm:text-lg font-semibold text-light/90">
                        {v.title}
                      </h3>
                      <p className="mt-2 text-sm sm:text-base text-light/70 leading-relaxed">
                        {v.text}
                      </p>
                    </div>
                  ))
                : null}
            </div>
          </div>
        </div>
      </section>

      {/* FAQ */}
      <section className="py-10 sm:py-14">
        <div className={styles.container}>
          <div className="mx-auto max-w-4xl">
            <h2 className="text-2xl sm:text-4xl text-center poppins-regular text-verde">
              {t("about.faq.title")}
            </h2>

            <div className="mt-8 space-y-3">
              {Array.isArray(faq)
                ? faq.map((x, idx) => (
                    <details key={`${x.q}-${idx}`} className={styles.card}>
                      <summary className="cursor-pointer text-sm sm:text-base font-semibold text-light/90">
                        {x.q}
                      </summary>
                      <p className="mt-3 text-sm sm:text-base text-light/70 leading-relaxed">
                        {x.a}
                      </p>
                    </details>
                  ))
                : null}
            </div>
          </div>
        </div>
      </section>

      {/* FINAL CTA */}
      <section className="py-12 sm:py-16">
        <div className={styles.container}>
          <div className="mx-auto max-w-4xl text-center">
            <h2 className="text-2xl sm:text-4xl poppins-regular text-verde">
              {t("about.finalCta.title")}
            </h2>
            <p className="mt-4 text-sm sm:text-base text-light/70">
              {t("about.finalCta.subtitle")}
            </p>

            <div className="mt-8 flex flex-col sm:flex-row items-center justify-center gap-3">
              <Link
                to="/contact/"
                className="rounded-full bg-secondary px-5 py-2.5 text-light text-center"
              >
                {t("about.finalCta.primary")}
              </Link>
              <a
                href={mailto}
                className="rounded-full bg-purplesemilight px-5 py-2.5 text-light text-center"
              >
                {t("about.finalCta.secondary")}
              </a>
            </div>
          </div>
        </div>
      </section>
    </Layout>
  );
};

export default AboutPage;

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;

const styles = {
  sectionWrapper:
    "border-2 w-full sm:w-[1024px] mx-auto rounded-xl p-2 sm:p-8 mt-8 bg-darkBg/50",
  labelTitle: "text-2xl sm:text-4xl text-center poppins-regular text-verde",
  container: "mx-auto w-full max-w-6xl px-4 sm:px-6",
  card: "rounded-2xl border border-black/10 bg-primary/70 p-5 shadow-sm supports-[backdrop-filter]:bg-purplesemilight/40 supports-[backdrop-filter]:backdrop-blur text-light",
  cardTitle: "text-base sm:text-lg font-semibold text-light/90",
  cardText: "mt-3 text-sm sm:text-base text-light/70 leading-relaxed",
};
